def transform(grid):
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]
    marker = next(((r, c - 8) for r, row in enumerate(grid)
                   for c, value in enumerate(row) if value == 5 and c >= 8), None)
    if marker is None:
        return out
    mr, start_c = marker
    r, c = mr, start_c  # each new segment starts one row below the previous endpoint

    # Read all symbol tiles down the left column, then down the right column.
    tiles = []
    for x in (0, 4):
        for y in range(0, h - 2, 4):
            mask = {(dy, dx) for dy in range(3) for dx in range(3)
                    if grid[y + dy][x + dx] not in (0, 4, 5)}
            vals = [grid[y + dy][x + dx] for dy in range(3) for dx in range(3)
                    if grid[y + dy][x + dx] not in (0, 4, 5)]
            if not vals:
                continue
            color = vals[0]
            if mask == {(0,0),(0,1),(1,0),(1,2),(2,1)}:       # right, 3 cells
                direction, length = 1, 3
            elif mask == {(0,0),(0,2),(1,0),(1,2),(2,0),(2,1),(2,2)}: # left, 2
                direction, length = -1, 2
            elif mask == {(0,0),(0,2),(1,1),(2,1)}:           # down, 2
                direction, length = 0, 2
            elif mask == {(0,0),(0,1),(0,2),(1,1),(2,0),(2,2)}: # left, 4
                direction, length = -1, 4
            else:
                return out
            tiles.append((color, direction, length))

    if 0 <= mr < h and 0 <= start_c < 7:
        out[mr][start_c] = 5
    for color, direction, length in tiles:
        r += 1
        if direction == 0:
            for k in range(length):
                if 0 <= r + k < h and 0 <= c < 7:
                    out[r + k][c] = color
            r += length - 1
        elif direction > 0:
            for k in range(length):
                if 0 <= r < h and 0 <= c + k < 7:
                    out[r][c + k] = color
            c += length - 1
        else:
            for k in range(length):
                if 0 <= r < h and 0 <= c - k < 7:
                    out[r][c - k] = color
            c -= length - 1
    return out
